uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float intensity : 0.0 .. 2.0 = 1.0;
uniform vec3 tint : color = 1.0, 0.15, 0.05;

state float ph;
state float tail;

void update() {
  ph = fract(ph + dt * speed * 1.25);
  tail = 0.30 + 0.05 * sin(ph * 6.2832);
}

vec3 shade(Led led) {
  fixed r2 = fixed(led.pos.x) * fixed(led.pos.x) + fixed(led.pos.z) * fixed(led.pos.z);
  fixed h2 = fixed(led.pos.y) * fixed(led.pos.y);
  fixed d2 = r2 + h2;
  fixed rmax2 = fixed(0.0064 + 0.0225);   // 0.08^2 + 0.15^2
  fixed norm = d2 / rmax2;                // 0 at centre, 1 at rim
  fixed phase = fract(fixed(ph) - norm);
  fixed pulse = clamp(fixed(1.0) - phase / fixed(tail), fixed(0.0), fixed(1.0));
  pulse = pulse * pulse;
  return hsv2rgb(fixed(0.0), fixed(0.9), pulse * fixed(intensity));
}
